/** 工具回执正文的健壮化（tool_result / observation 共用同一口径）。
 *
 *  `ToolResult.output: string` 只约束**我们自己的**工具；插件、MCP、脚本化工具都是运行期才到手，
 *  返回 `{ok:true}`（缺 output）/ `output:null` / `output:{…}` 都完全可能，跨进程边界管不到。
 *  - 字符串原样返回（正常回执逐字不变，不为了安全全包一层）；
 *  - `undefined`（缺 output）给一句可读占位（含「没有正文」），绝不落成字面量 "undefined"；
 *  - `null` 单独成串（含 "null"），与「缺失」分得开；
 *  - 对象/数组走循环引用安全的 JSON 序列化（不是 "[object Object]"）；
 *  - 其它（number/boolean 等）String()。
 *  空串 `""` 原样返回——「真的没输出」是一个事实，不被占位符顶替。 */
export function coerceToolOutputText(output: unknown): string {
  if (typeof output === "string") return output;
  if (output === undefined) return "[工具没有返回正文（output 缺失）]";
  if (output === null) return "[工具返回 output 为 null]";
  if (typeof output === "object") return safeJsonSummary(output);
  return String(output);
}

/** 观察摘要（tool_result → 稳定可比的 observation 串；截断防长输出抖动）。
